// Detecta si el WhatsApp de alguna agencia está caído: en las últimas 3 h hay 2+ envíos fallidos y ninguno entregado.
// No cuenta los fallos normales de "más de 24 h sin respuesta del cliente". Avisa al caer, recuerda cada 6 h y avisa al recuperarse.
// También avisa: al primer error de número desconectado de Meta (p. ej. #133010 "Account not registered"), y si una agencia
// que normalmente recibe mensajes lleva más de 2 h sin recibir ninguno en horario (10–21 h): suele ser que el número se desconectó de GHL.
const AGENCIAS = ['Independencia', 'Centro', 'Periodismo', 'Matriz', 'Hijar'];
const est = $getWorkflowStaticData('global');
est.agencias = est.agencias || {};
const ahora = Date.now();
const correos = [];
for (const ag of AGENCIAS) {
  let r = {};
  try { r = $('WhatsApp ' + ag).first().json || {}; } catch (e) {}
  const prevEst = est.agencias[ag] || { caido: false, ultimoAviso: 0 };
  if (r.error || !Array.isArray(r.messages)) {
    correos.push({ asunto: `⚠️ No se pudo revisar el WhatsApp de ${ag}`, cuerpo: `No se pudieron consultar los mensajes de WhatsApp de RS Viajes ${ag} en GHL.\nDetalle: ${JSON.stringify(r.error || r).slice(0, 400)}\n\nPuede ser un problema temporal de GHL o de la credencial de la API.` , solo_si: !prevEst.errorApi });
    est.agencias[ag] = { ...prevEst, errorApi: true };
    continue;
  }
  const salientes = r.messages.filter(m => m.direction === 'outbound');
  const fallidos = salientes.filter(m => m.status === 'failed' && !/24 hours/i.test(String(m.error || '')));
  const okCount = salientes.filter(m => ['delivered', 'read', 'sent'].includes(m.status)).length;
  const entrantes = r.messages.filter(m => m.direction === 'inbound').length;
  const desconectado = fallidos.filter(m => /133010|133005|131031|not registered|account (is )?locked|disconnected/i.test(String(m.error || '')));
  const ultimoOk = Math.max(0, ...salientes.filter(m => ['delivered', 'read', 'sent'].includes(m.status)).map(m => new Date(m.dateAdded).getTime()));
  // Un error de número desconectado posterior al último mensaje entregado ya cuenta como caída
  const caido = (fallidos.length >= 2 && okCount === 0) || desconectado.some(m => new Date(m.dateAdded).getTime() > ultimoOk);
  const errores = [...new Set(fallidos.map(m => String(m.error || 'sin detalle').slice(0, 160)))];
  // Silencio: sin mensajes de clientes en las últimas 2 h, en horario, en una agencia con movimiento habitual
  const hora = Number(new Date().toLocaleString('en-US', { timeZone: 'America/Mexico_City', hour: 'numeric', hour12: false }));
  const ultimaEntrada = Math.max(0, ...r.messages.filter(m => m.direction === 'inbound').map(m => new Date(m.dateAdded).getTime()));
  // Mensajes de clientes que suelen entrar cada 3 h en horario (medido el 10–13 oct); luego se ajusta solo
  const INICIAL = { Independencia: 3, Centro: 5, Periodismo: 6, Matriz: 9, Hijar: 0 };
  if (prevEst.versionMedia !== 2) { prevEst.mediaEntrantes = INICIAL[ag]; prevEst.versionMedia = 2; }
  const media = prevEst.mediaEntrantes;
  const enHorario = hora >= 10 && hora < 21;
  // Agencias con mucho movimiento: 2 h sin mensajes ya es raro; con poco movimiento, 3 h (toda la ventana)
  const silencio = enHorario && media >= 3 && (ahora - ultimaEntrada) > (media >= 6 ? 2 : 2.9) * 3600 * 1000;
  if (enHorario && !silencio) prevEst.mediaEntrantes = Math.round((media * 0.9 + entrantes * 0.1) * 10) / 10;
  else prevEst.mediaEntrantes = media;
  if (silencio && !caido && (!prevEst.silencio || ahora - (prevEst.avisoSilencio || 0) > 6 * 3600 * 1000)) {
    correos.push({ asunto: `🔇 RS Viajes ${ag}: no entran mensajes de WhatsApp`, cuerpo:
      `Desde ${ultimaEntrada ? new Date(ultimaEntrada).toLocaleTimeString('es-MX', { timeZone: 'America/Mexico_City', hour: '2-digit', minute: '2-digit' }) : 'hace más de 3 horas'} no ha entrado ningún mensaje de clientes por WhatsApp a GHL en RS Viajes ${ag}, ` +
      `y normalmente entran unos ${Math.round(media)} cada 3 horas.\n\nSuele pasar cuando el número se desconecta de GHL (por ejemplo, si se abrió en otro celular o en la app de WhatsApp Business). ` +
      `Pregunta en la agencia si les están llegando mensajes al celular que no aparecen en GHL y revisa en GHL → subcuenta ${ag} → Configuración → WhatsApp el estado del número.` });
    prevEst.silencio = true; prevEst.avisoSilencio = ahora;
  } else if (!silencio) { prevEst.silencio = false; }
  if (caido && (!prevEst.caido || ahora - (prevEst.ultimoAviso || 0) > 6 * 3600 * 1000)) {
    correos.push({ asunto: `🚨 WhatsApp caído en RS Viajes ${ag}`, cuerpo:
      (desconectado.length ? `Meta indica que el número de WhatsApp de RS Viajes ${ag} está desconectado: fallaron ${fallidos.length} mensajes en las últimas 3 horas.\n` : `En las últimas 3 horas fallaron ${fallidos.length} mensajes de WhatsApp de RS Viajes ${ag} y no se entregó ninguno.\n`) +
      `Mensajes de clientes recibidos en ese tiempo: ${entrantes}.\n\nError de Meta:\n- ${errores.join('\n- ')}\n\n` +
      `Qué hacer: en GHL → subcuenta ${ag} → Configuración → WhatsApp, reconecta el número y revisa su estado en WhatsApp Manager de Meta. ` +
      `Mientras tanto, contesten desde la app de WhatsApp Business del celular.\n\nTe vuelvo a avisar cada 6 horas mientras siga fallando.` });
    est.agencias[ag] = { ...prevEst, caido: true, ultimoAviso: ahora, desde: prevEst.caido ? prevEst.desde : ahora };
  } else if (!caido && prevEst.caido && okCount > 0) {
    const horas = Math.round((ahora - (prevEst.desde || ahora)) / 3600000);
    correos.push({ asunto: `✅ WhatsApp de RS Viajes ${ag} recuperado`, cuerpo:
      `El WhatsApp de RS Viajes ${ag} vuelve a entregar mensajes (${okCount} entregados en las últimas 3 horas). Estuvo fallando unas ${horas} h.\n\n` +
      `Revisa los mensajes que fallaron en ese tiempo para reenviarlos, y la app del celular por si algún cliente escribió y no entró a GHL.` });
    est.agencias[ag] = { ...prevEst, caido: false, ultimoAviso: 0 };
  } else {
    est.agencias[ag] = { ...prevEst, errorApi: false, caido: caido || (prevEst.caido && okCount === 0) };
  }
}
return correos.filter(c => c.solo_si !== false).map(c => ({ json: { asunto: c.asunto, cuerpo: c.cuerpo } }));
